#pragma once
#include <stddef.h>
#include <stdint.h>

// Vendor and device names from pci.ids. Both arrays are sorted by ID; a vendor's
// devices are devices[first .. first + count). Names are offsets into `strings`.
struct pci_db_vendor {
    uint16_t id, count;
    uint32_t name, first;
};

struct pci_db_device {
    uint16_t id;
    uint32_t name;
};

struct pci_db {
    const char *strings;
    const struct pci_db_vendor *vendors;
    size_t nvendors;
    const struct pci_db_device *devices;
    size_t ndevices;
    const char *version;  // the pci.ids version line
};

// Generated by tools/pciids2c.py into src/info/pci_ids.c.
extern const struct pci_db pci_ids;

// Pure: binary searches; NULL when the ID is not listed.
const char *pci_db_vendor(const struct pci_db *db, uint16_t vendor);
const char *pci_db_device(const struct pci_db *db, uint16_t vendor, uint16_t device);
